import { useState, useEffect } from 'react';
import { useTranslation } from 'react-i18next';
import { api } from '../core/api/client';

interface Props {
  provider: string;
  currentModel: string;
  onChanged: () => void;
}

export function ModelSelector({ provider, currentModel, onChanged }: Props) {
  const { t } = useTranslation();

  const [models, setModels] = useState<string[]>([]);
  const [selected, setSelected] = useState(currentModel);
  const [saving, setSaving] = useState(false);

  useEffect(() => {
    api<{ models: string[] }>(`/api/providers/${provider}/models`)
      .then(data => setModels(data.models))
      .catch(console.error);
  }, [provider]);

  async function save(model: string) {
    setSaving(true);
    try {
      await api('/api/providers/active', {
        method: 'PUT',
        body: JSON.stringify({ provider, model }),
      });
      setSelected(model);
      onChanged();
    } catch (err) {
      console.error('Failed to set model:', err);
    } finally {
      setSaving(false);
    }
  }

  if (!models.length) return null;

  return (
    <div>
      <label style={{
        display: 'block',
        fontFamily: "'JetBrains Mono', ui-monospace, monospace",
        fontSize: 9, letterSpacing: '0.16em', textTransform: 'uppercase',
        color: 'rgba(237,240,244,0.38)', marginBottom: 6,
      }}>
        {t('providers.model')}
      </label>
      <select
        value={selected}
        onChange={e => save(e.target.value)}
        disabled={saving}
        style={{
          width: '100%', boxSizing: 'border-box',
          background: 'rgba(34,40,48,0.55)', border: '1px solid rgba(230,235,242,0.14)',
          color: '#EDF0F4', borderRadius: 4, padding: '8px 12px', fontSize: 13,
          outline: 'none', opacity: saving ? 0.5 : 1,
        }}
      >
        {models.map(m => (
          <option key={m} value={m}>{m}</option>
        ))}
      </select>
    </div>
  );
}

import { useState, useEffect } from 'react';
import { useTranslation } from 'react-i18next';
import { api } from '../core/api/client';
import type { ProviderStatus } from '../core/types';
import { ApiKeyEntry } from './ApiKeyEntry';
import { SetupTokenEntry } from './SetupTokenEntry';
import { ModelSelector } from './ModelSelector';
import { TierPicker } from './TierPicker';
import { OllamaSetup } from './OllamaSetup';
import { TogetherSetup } from './TogetherSetup';
import { IconBrain, IconZap, IconSparkle, IconGlobe, IconHome } from '../shared/icons';

const PROVIDER_ICONS: Record<string, React.ComponentType<{ size?: number; className?: string; strokeWidth?: number }>> = {
  anthropic: IconBrain,
  openai: IconZap,
  deepseek: IconZap,
  kimi: IconSparkle,
  google: IconSparkle,
  together: IconGlobe,
  ollama: IconHome,
};

type AuthTab = 'setup-token' | 'api-key' | 'ollama-setup' | 'together-setup';

const mono = (size: number, color = 'rgba(237,240,244,0.38)') => ({
  fontFamily: "'JetBrains Mono', ui-monospace, monospace",
  fontSize: size, letterSpacing: '0.16em',
  textTransform: 'uppercase' as const, color,
});

export function ProviderSetup() {
  const { t } = useTranslation();

  const [status, setStatus] = useState<ProviderStatus | null>(null);
  const [loading, setLoading] = useState(true);
  const [authTab, setAuthTab] = useState<Record<string, AuthTab>>({});

  function reload() {
    api<ProviderStatus>('/api/providers')
      .then(setStatus)
      .catch(console.error)
      .finally(() => setLoading(false));
  }

  useEffect(() => { reload(); }, []);

  if (loading) return (
    <div style={{ display: 'flex', justifyContent: 'center', padding: '32px 0' }}>
      <div className="w-6 h-6 border-2 border-ch-accent border-t-transparent rounded-full animate-spin" />
    </div>
  );

  const providers = [
    {
      id: 'anthropic',
      name: 'Anthropic (Claude)',
      tabs: [{ id: 'api-key' as AuthTab, label: t('providers.apiKey') }],
      defaultTab: 'api-key' as AuthTab,
    },
    {
      id: 'openai',
      name: 'OpenAI (GPT)',
      tabs: [{ id: 'api-key' as AuthTab, label: t('providers.apiKey') }],
      defaultTab: 'api-key' as AuthTab,
    },
    {
      id: 'deepseek',
      name: 'DeepSeek',
      tabs: [{ id: 'api-key' as AuthTab, label: t('providers.apiKey') }],
      defaultTab: 'api-key' as AuthTab,
    },
    {
      id: 'kimi',
      name: 'Kimi',
      tabs: [{ id: 'api-key' as AuthTab, label: t('providers.apiKey') }],
      defaultTab: 'api-key' as AuthTab,
    },
    {
      id: 'google',
      name: 'Google (Gemini)',
      tabs: [{ id: 'api-key' as AuthTab, label: t('providers.apiKey') }],
      defaultTab: 'api-key' as AuthTab,
    },
    {
      id: 'together',
      name: 'Together AI',
      tabs: [{ id: 'together-setup' as AuthTab, label: t('providers.apiKey') }],
      defaultTab: 'together-setup' as AuthTab,
    },
    ...(!status?.is_railway
      ? [{
          id: 'ollama',
          name: 'Ollama (Local)',
          tabs: [{ id: 'ollama-setup' as AuthTab, label: t('providers.localSetup') }],
          defaultTab: 'ollama-setup' as AuthTab,
        }]
      : []),
  ];

  function getTab(providerId: string): AuthTab {
    return authTab[providerId] || providers.find(p => p.id === providerId)!.defaultTab;
  }

  function renderConnectUI(p: typeof providers[0]) {
    const tab = getTab(p.id);
    return (
      <div>
        {p.tabs.length > 1 && (
          <div style={{ display: 'flex', gap: 8, marginBottom: 12 }}>
            {p.tabs.map(t => (
              <button key={t.id} onClick={() => setAuthTab(prev => ({ ...prev, [p.id]: t.id }))}
                style={{
                  padding: '4px 12px', borderRadius: 4, fontSize: 11, fontWeight: 500,
                  background: tab === t.id ? 'rgba(200,209,217,0.12)' : 'transparent',
                  color: tab === t.id ? '#EDF0F4' : 'rgba(237,240,244,0.62)',
                  border: `1px solid ${tab === t.id ? 'rgba(200,209,217,0.3)' : 'rgba(230,235,242,0.14)'}`,
                  cursor: 'pointer',
                }}
              >{t.label}</button>
            ))}
          </div>
        )}
        {tab === 'setup-token' && <SetupTokenEntry onConnected={reload} />}
        {tab === 'api-key' && <ApiKeyEntry provider={p.id} onConnected={reload} />}
        {tab === 'together-setup' && <TogetherSetup onConnected={reload} />}
        {tab === 'ollama-setup' && <OllamaSetup onConnected={reload} />}
      </div>
    );
  }

  return (
    <div style={{ display: 'flex', flexDirection: 'column', gap: 8 }}>
      {providers.map(p => {
        const profile = status?.profiles?.[p.id];
        const isConnected = profile?.configured ?? false;
        const isActive = status?.active_provider === p.id;
        const currentModel = isActive ? (status?.active_model ?? '') : '';

        return (
          <div key={p.id} style={{
            background: 'rgba(20,24,30,0.78)',
            borderRadius: 6, padding: 20,
            border: `1px solid ${isActive ? 'rgba(200,209,217,0.3)' : 'rgba(230,235,242,0.07)'}`,
          }}>
            <div style={{ display: 'flex', alignItems: 'center', justifyContent: 'space-between', marginBottom: 16 }}>
              <div style={{ display: 'flex', alignItems: 'center', gap: 12 }}>
                <div style={{
                  width: 32, height: 32, borderRadius: 4,
                  background: 'rgba(245,239,227,0.06)',
                  border: '1px solid rgba(230,235,242,0.07)',
                  display: 'flex', alignItems: 'center', justifyContent: 'center',
                  color: 'rgba(237,240,244,0.62)',
                }}>
                  {(() => { const Icon = PROVIDER_ICONS[p.id] || IconGlobe; return <Icon size={16} strokeWidth={1.75} />; })()}
                </div>
                <div>
                <p style={{
                  fontFamily: "'Fraunces', Georgia, serif",
                  fontSize: 16, letterSpacing: '-0.01em', color: '#EDF0F4', margin: 0,
                }}>{p.name}</p>
                {isActive && (
                  <span style={{ ...mono(9, '#D4A85A'), marginTop: 2, display: 'inline-block' }}>
                    {t('providers.active')}
                  </span>
                )}
                </div>
              </div>

              {isConnected && (
                <div style={{ display: 'flex', alignItems: 'center', gap: 8 }}>
                  {profile?.expired && (
                    <span style={{ fontSize: 11, color: '#D4A85A', border: '1px solid rgba(212,168,90,0.3)', borderRadius: 4, padding: '2px 6px' }}>
                      {t('providers.expired')}
                    </span>
                  )}
                  <span style={{ width: 6, height: 6, borderRadius: '50%', background: '#8EA589' }} />
                  <span style={{ ...mono(10, '#8EA589') }}>
                    {t('providers.connected')}
                  </span>
                </div>
              )}
            </div>

            {!isConnected ? renderConnectUI(p) : (
              <div style={{ display: 'flex', flexDirection: 'column', gap: 8 }}>
                <ModelSelector provider={p.id} currentModel={currentModel} onChanged={reload} />
                {p.id !== 'ollama' && <TierPicker provider={p.id} onChanged={reload} />}
                {!isActive && (
                  <button onClick={async () => {
                    await api('/api/providers/active', { method: 'PUT', body: JSON.stringify({ provider: p.id, model: currentModel || '' }) });
                    reload();
                  }} style={{
                    width: '100%', padding: '8px 16px', fontSize: 13, borderRadius: 4,
                    border: '1px solid rgba(200,209,217,0.3)', color: 'var(--color-ch-accent, #C8D1D9)',
                    background: 'transparent', cursor: 'pointer',
                  }}>
                    {t('providers.setAsActive')}
                  </button>
                )}
                <button onClick={async () => {
                  await api(`/api/providers/${p.id}/disconnect`, { method: 'POST' });
                  reload();
                }} style={{
                  width: '100%', padding: '8px 16px', fontSize: 13, borderRadius: 4,
                  border: '1px solid rgba(217,119,87,0.3)', color: '#D97757',
                  background: 'transparent', cursor: 'pointer',
                }}>
                  {t('providers.disconnect')}
                </button>
              </div>
            )}
          </div>
        );
      })}
    </div>
  );
}

import { useState, useEffect } from 'react';
import { useTranslation } from 'react-i18next';
import { api } from '../core/api/client';

interface Props {
  provider: string;
  onChanged?: () => void;
}

const TIERS: Array<'top' | 'mid' | 'light'> = [
  'top',
  'mid',
  'light',
];

const selectStyle: React.CSSProperties = {
  width: '100%', boxSizing: 'border-box',
  background: 'rgba(34,40,48,0.55)', border: '1px solid rgba(230,235,242,0.14)',
  color: '#EDF0F4', borderRadius: 4, padding: '6px 8px', fontSize: 12, outline: 'none',
};

const captionStyle: React.CSSProperties = {
  fontFamily: "'JetBrains Mono', ui-monospace, monospace",
  fontSize: 9, letterSpacing: '0.16em', textTransform: 'uppercase',
  color: 'rgba(237,240,244,0.38)',
};

/**
 * Lets the user override which concrete model each tier (top/mid/light) maps to.
 * Options come from the (cached) live model list; defaults are the inferred
 * values returned by /api/providers/tiers. Saving PUTs a single-tier override.
 */
export function TierPicker({ provider, onChanged }: Props) {
  const { t } = useTranslation();

  const [models, setModels] = useState<string[]>([]);
  const [tiers, setTiers] = useState<Record<string, string>>({});
  const [saving, setSaving] = useState(false);

  useEffect(() => {
    api<{ models: string[] }>(`/api/providers/${provider}/models`)
      .then(d => setModels(d.models))
      .catch(console.error);
    api<{ tier_models: Record<string, Record<string, string>> }>('/api/providers/tiers')
      .then(d => setTiers(d.tier_models?.[provider] || {}))
      .catch(console.error);
  }, [provider]);

  async function save(tier: string, model: string) {
    const previous = tiers[tier] ?? '';
    setSaving(true);
    setTiers(prev => ({ ...prev, [tier]: model }));  // optimistic
    try {
      await api('/api/providers/tiers', {
        method: 'PUT',
        body: JSON.stringify({ provider, models: { [tier]: model } }),
      });
      onChanged?.();
    } catch (err) {
      console.error('Failed to set tier:', err);
      setTiers(prev => ({ ...prev, [tier]: previous }));  // roll back on failure
    } finally {
      setSaving(false);
    }
  }

  function getTierLabel(tier: 'top' | 'mid' | 'light'): string {
    const labels = {
      top: t('providers.tierTop'),
      mid: t('providers.tierMid'),
      light: t('providers.tierLight'),
    };

    return labels[tier];
  }

  if (!models.length) return null;

  // Keep the current resolved value selectable even if it's not in the live list.
  const optionsFor = (current: string) =>
    !current || models.includes(current) ? models : [current, ...models];

  return (
    <div>
      <label style={{ ...captionStyle, display: 'block', marginBottom: 6 }}>
        {t('providers.tiers')}
      </label>
      <div style={{ display: 'flex', gap: 8 }}>
        {TIERS.map(tier => (
          <div key={tier} style={{ flex: 1, minWidth: 0 }}>
            <span style={{ ...captionStyle, display: 'block', marginBottom: 4 }}>
              {getTierLabel(tier)}
            </span>
            <select
              value={tiers[tier] || ''}
              onChange={e => save(tier, e.target.value)}
              disabled={saving}
              style={{ ...selectStyle, opacity: saving ? 0.5 : 1 }}
            >
              <option value="">
                {t('providers.useInferredDefault')}
              </option>

              {optionsFor(tiers[tier] || '').map(m => (
                <option key={m} value={m}>
                  {m}
                </option>
              ))}
            </select>
          </div>
        ))}
      </div>
    </div>
  );
}

import { useState } from 'react';
import { useTranslation } from 'react-i18next';
import { api } from '../core/api/client';

interface Props {
  provider: string;
  onConnected: () => void;
}

const API_KEY_LINKS: Record<string, string> = {
  anthropic: 'https://console.anthropic.com/settings/keys',
  openai: 'https://platform.openai.com/api-keys',
  google: 'https://aistudio.google.com/apikey',
  deepseek: 'https://platform.deepseek.com/api_keys',
  kimi: 'https://platform.moonshot.ai/console/api-keys',
};

const inputStyle: React.CSSProperties = {
  width: '100%', boxSizing: 'border-box',
  background: 'rgba(34,40,48,0.55)', border: '1px solid rgba(230,235,242,0.14)',
  color: '#EDF0F4', borderRadius: 4, padding: '10px 14px', fontSize: 13, outline: 'none',
};

export function ApiKeyEntry({ provider, onConnected }: Props) {
  const { t } = useTranslation();

  const [key, setKey] = useState('');
  const [loading, setLoading] = useState(false);
  const [error, setError] = useState('');

  async function connect() {
    if (!key.trim()) return;
    setLoading(true); setError('');
    try {
      const endpoint = (provider === 'openai' || provider === 'google')
        ? `/api/providers/${provider}/connect-key`
        : `/api/providers/${provider}/connect`;
      await api(endpoint, {
        method: 'POST',
        body: JSON.stringify({ api_key: key.trim() }),
      });
      onConnected();
    } catch (err: unknown) {
      setError(
        err instanceof Error
          ? err.message
          : t('providers.invalidApiKey')
      );
    } finally {
      setLoading(false);
    }
  }

  function getApiKeyLinkLabel(providerId: string): string {
    const labels: Record<string, string> = {
      anthropic: t('providers.getAnthropicApiKey'),
      openai: t('providers.getOpenAIApiKey'),
      google: t('providers.getGoogleApiKey'),
      deepseek: t('providers.getDeepSeekApiKey'),
      kimi: t('providers.getKimiApiKey'),
    };

    return labels[providerId] || '';
  }

  return (
    <div style={{ display: 'flex', flexDirection: 'column', gap: 10 }}>
      <input
        type="password"
        value={key}
        onChange={e => setKey(e.target.value)}
        placeholder={
          provider === 'anthropic'
            ? 'sk-ant-...'
            : provider === 'google'
              ? 'AIza...'
              : 'sk-...'
        }
        onKeyDown={e => e.key === 'Enter' && connect()}
        style={inputStyle}
      />
      {error && <p style={{ color: '#D97757', fontSize: 12 }}>{error}</p>}
      {API_KEY_LINKS[provider] && (
        <a
          href={API_KEY_LINKS[provider]}
          target="_blank"
          rel="noopener noreferrer"
          style={{
            fontSize: 12,
            color: 'var(--color-ch-accent, #C8D1D9)',
            textDecoration: 'none',
          }}
        >
          {getApiKeyLinkLabel(provider)} &rarr;
        </a>
      )}
      <button
        onClick={connect}
        disabled={loading || !key.trim()}
        style={{
          width: '100%', padding: '9px 16px', borderRadius: 4,
          background: 'var(--color-ch-accent, #C8D1D9)', color: '#0E1013',
          border: 'none', fontSize: 13, fontWeight: 500,
          cursor: 'pointer', opacity: (loading || !key.trim()) ? 0.5 : 1,
        }}
      >
        {loading
          ? t('providers.validating')
          : t('providers.connect')}
      </button>
    </div>
  );
}

