// Chatty — shared TypeScript types

export interface Agent {
  id: string;
  slug: string;
  agent_name: string;
  avatar_url: string;
  personality: string;
  project_root: string;
  onboarding_complete: boolean;
  provider_override: string;
  model_override: string;
  gmail_enabled: boolean;
  gmail_send_enabled?: boolean;
  calendar_enabled: boolean;
  calendar_write_enabled?: boolean;
  drive_enabled?: boolean;
  drive_write_enabled?: boolean;
  google_accounts?: { gmail?: string[]; calendar?: string[]; drive?: string[] };
  whatsapp_session_id?: string;
  telegram_enabled: boolean;
  telegram_bot_token?: string;
  telegram_bot_username?: string;
  telegram_group_enabled: boolean;
  alert_count?: number;
  created_at: string;
  updated_at: string;
}

export interface AgentAlert {
  id: string;
  agent: string;
  source: string;
  source_id: string | null;
  title: string;
  message: string;
  status: 'active' | 'acknowledged' | 'resolved';
  created_at: string;
  acknowledged_at: string | null;
  resolved_at: string | null;
}

export interface AgentNotification {
  id: string;
  agent: string;
  title: string;
  message: string;
  status: 'active' | 'dismissed';
  channels_sent: string[];
  created_at: string;
  dismissed_at: string | null;
}

export interface Reminder {
  id: string;
  agent: string;
  message: string;
  context: string | null;
  due_at: string;
  status: 'pending' | 'fired' | 'cancelled';
  created_at: string;
  fired_at: string | null;
  result: string | null;
  recurrence_rule: string | null;
  series_id: string | null;
  is_recurring: boolean;
}

export interface Commitment {
  id: number;
  agent_slug: string;
  text: string;
  due_at: string | null;
  source_conversation_id: string | null;
  status: 'active' | 'done' | 'dismissed' | 'expired';
  created_at: string;
  surfaced_count: number;
  last_surfaced_at: string | null;
}

export type GmailScopeLevel = 'none' | 'read' | 'send';
export type CalendarScopeLevel = 'none' | 'read' | 'full';
export type DriveScopeLevel = 'none' | 'file' | 'readonly' | 'full';

export interface GoogleScopeGrants {
  gmail: GmailScopeLevel;
  calendar: CalendarScopeLevel;
  drive: DriveScopeLevel;
}

export interface GoogleAccount {
  id: string;
  email: string;
  scope_grants: GoogleScopeGrants;
  connection_status: string;
}

export interface Conversation {
  id: string;
  title: string;
  title_edited_by_user: boolean;
  source?: string | null;
  pinned?: number;
  mode?: 'normal' | 'import';
  created_at: string;
  updated_at: string;
  message_count?: number;
  preview?: string;
}

export interface Message {
  id: string;
  conversation_id: string;
  role: 'user' | 'assistant';
  content: string;
  created_at: string;
  seq: number;
}

export interface Provider {
  id: string;
  name: string;
  connected: boolean;
  active: boolean;
  model?: string;
}

export interface BrandingConfig {
  company_name: string;
  accent_color: string;
  has_logo: boolean;
}

export interface Integration {
  id: string;
  name: string;
  description: string;
  icon: string;
  auth_type: string;
  enabled: boolean;
  configured: boolean;
  always_on?: boolean;
  deprecated?: boolean;
  connection_status?: string;
  tool_mode?: string;
  email?: string;
  scope_grants?: GoogleScopeGrants;
  google_accounts?: GoogleAccount[];
  has_app_credentials?: boolean;
  app_id?: string;
  agent_id?: string;
  corp_id?: string;
  app_agent_id?: string;
  has_corp_secret?: boolean;
  has_callback_token?: boolean;
  has_encoding_aes_key?: boolean;
  has_app_secret?: boolean;
}

// CRM types

export interface CrmContact {
  id: number;
  name: string;
  email: string;
  phone: string;
  company: string;
  title: string;
  source: string;
  status: string;
  tags: string;
  notes: string;
  created_at: string;
  updated_at: string;
  // Detail view extras
  deals?: CrmDeal[];
  tasks?: CrmTask[];
  activity?: CrmActivity[];
}

export interface CrmDeal {
  id: number;
  contact_id: number | null;
  contact_name?: string;
  title: string;
  stage: string;
  value: number;
  notes: string;
  expected_close_date: string;
  probability: number;
  currency: string;
  created_at: string;
  updated_at: string;
  activity?: CrmActivity[];
}

export interface CrmTask {
  id: number;
  contact_id: number | null;
  deal_id: number | null;
  contact_name?: string;
  deal_title?: string;
  title: string;
  description: string;
  due_date: string;
  completed: number;
  priority: string;
  created_at: string;
  updated_at: string;
}

export interface CrmActivity {
  id: number;
  contact_id: number | null;
  deal_id: number | null;
  contact_name?: string;
  deal_title?: string;
  activity: string;
  note: string;
  created_at: string;
}

export interface CrmDashboard {
  total_contacts: number;
  contacts_by_status: Record<string, number>;
  pipeline_by_stage: { stage: string; count: number; total_value: number }[];
  total_pipeline_value: number;
  overdue_tasks: number;
  pending_tasks: number;
  recent_activity: CrmActivity[];
  top_deals: CrmDeal[];
}

// Provider status (from GET /api/providers)
export interface ProviderStatus {
  active_provider: string;
  active_model: string;
  is_railway?: boolean;
  profiles: Record<string, {
    type: string;
    configured: boolean;
    key_preview?: string;
    expired?: boolean;
    base_url?: string;
  }>;
}

// Context usage (returned from SSE 'usage' event)
// contextTokens is the cache-inclusive total the model read this turn (how full
// the context window is); contextWindow is the model's window size.
export interface ContextUsage {
  contextTokens: number;
  contextWindow: number;
}

// Tool mode for 3-tier tool permissions
export type ToolMode = 'read-only' | 'normal' | 'power';

// Training type for onboarding vs improve flows
export type TrainingType = 'topic' | 'improve' | null;

// SSE event types
export type SSEEvent =
  | { type: 'conversation_id'; id: string }
  | { type: 'text'; text: string }
  | { type: 'tool_start'; tool: string; tool_use_id: string }
  | { type: 'tool_args'; tool: string; tool_use_id: string; args: Record<string, unknown>; description?: string }
  | { type: 'tool_end'; tool: string; tool_use_id: string; result: unknown; elapsed_ms?: number; duration_ms?: number }
  | { type: 'confirm'; tool: string; args: Record<string, unknown>; tool_use_id: string; msg_id?: string; description: string }
  | { type: 'plan_ready'; plan: string }
  | { type: 'usage'; input_tokens: number; output_tokens: number; context_tokens: number; context_window: number }
  | { type: 'report'; report: { id: string; title: string; subtitle?: string; sections: unknown[]; created_at: string } }
  | { type: 'title_update'; title: string; conversation_id: string }
  | { type: 'done'; model?: string; tier?: string }
  | { type: 'error'; error: string };

"""Chatty — Model tier definitions, inference, and resolution.

Tier labels (top/mid/light) map to concrete model IDs per provider. The
mapping is resolved synchronously (resolve_tier_model) as override -> inferred
-> hardcoded fallback; see model_tiers.py. infer_tier_models() produces the
name-based default from a live model list (called from the async listing path).
"""

from __future__ import annotations

import re


# Hardcoded fallback only. Resolution order is override -> inferred -> this map
# (see resolve_tier_model / model_tiers.py). Kept current by the price-check skill.
TIER_MODELS: dict[str, dict[str, str]] = {
    "anthropic": {
        "top":   "claude-opus-4-8",
        "mid":   "claude-sonnet-4-6",
        "light": "claude-haiku-4-5",
    },
    "openai": {
        "top":   "gpt-5.5",
        "mid":   "gpt-5.4-mini",
        "light": "gpt-5.4-nano",
    },
    "deepseek": {
        "top": "deepseek-v4-pro",
        "mid": "deepseek-v4-flash",
        "light": "deepseek-v4-flash",
    },
    "google": {
        "top":   "gemini-2.5-pro",
        "mid":   "gemini-2.5-flash",
        "light": "gemini-2.5-flash-lite",
    },
    "together": {
        "top":   "meta-llama/Llama-3.3-70B-Instruct-Turbo",
        "mid":   "google/gemma-4-31B-it",
        "light": "Qwen/Qwen3.5-9B",
    },
}

# Fallback display labels. The /tiers endpoint derives labels from the resolved
# model ids; these are used only when no resolved id is available.
TIER_LABELS: dict[str, dict[str, str]] = {
    "anthropic": {"top": "Opus", "mid": "Sonnet", "light": "Haiku"},
    "openai":    {"top": "GPT-5.5", "mid": "Mini", "light": "Nano"},
    "deepseek":  {"top": "Pro","mid": "Flash","light": "Flash",},
    "google":    {"top": "Pro", "mid": "Flash", "light": "Flash-Lite"},
    "together":  {"top": "70B", "mid": "31B", "light": "9B"},
}

# Hardcoded fallback for the triage classifier (the cheap "light"-tier model).
# get_triage_classifier() prefers override/inferred and falls back to this.
TRIAGE_CLASSIFIERS: dict[str, str] = {
    "anthropic": "claude-haiku-4-5",
    "openai":    "gpt-5.4-nano",
    "deepseek":  "deepseek-v4-flash",
    "google":    "gemini-2.5-flash-lite",
}


# ── Name-based tier inference (pure; no I/O) ───────────────────────────────────

def _version_key(model: str) -> tuple[int, ...]:
    return tuple(int(n) for n in re.findall(r"\d+", model))


def _best(candidates: list[str]) -> str | None:
    """Pick the highest-version candidate (ties broken by string)."""
    if not candidates:
        return None
    return max(candidates, key=lambda m: (_version_key(m), m))


def infer_tier_models(provider: str, available: list[str]) -> dict[str, str]:
    """Best-guess {top, mid, light} from a live model list, by naming.

    Pure function — no I/O. Falls back per-tier to the hardcoded TIER_MODELS
    entry when no candidate matches. The async listing path calls this and
    persists the result via model_tiers.set_inferred (live fetches only).
    """
    fb = TIER_MODELS.get(provider, {})
    av = [m for m in (available or []) if m]
    top = mid = light = None

    if provider == "anthropic":
        top = _best([m for m in av if "opus" in m.lower()])
        mid = _best([m for m in av if "sonnet" in m.lower()])
        light = _best([m for m in av if "haiku" in m.lower()])
    elif provider == "google":
        # Only real Gemini chat models. The live catalog also lists specialty
        # models whose names collide with the tier keywords — deep-research-pro,
        # lyria-3-pro (music), nano-banana-pro (image), TTS/image/robotics/
        # computer-use variants — some of which claim generateContent support
        # in metadata but reject it at call time ("only supports Interactions
        # API"), which would brick every chat turn routed to that tier.
        _specialty = ("image", "tts", "robotics", "computer-use", "customtools")
        g = [m for m in av
             if m.lower().startswith("gemini-")
             and not any(t in m.lower() for t in _specialty)]
        top = _best([m for m in g if "pro" in m.lower()])
        light = _best([m for m in g if "lite" in m.lower()])
        mid = _best([m for m in g if "flash" in m.lower() and "lite" not in m.lower()])
    elif provider == "openai":
        light = _best([m for m in av if "-nano" in m.lower()])
        mid = _best([m for m in av if "-mini" in m.lower()])
        top = _best([
            m for m in av
            if "-mini" not in m.lower() and "-nano" not in m.lower()
            and (m.lower().startswith("gpt-") or m.lower().startswith("o"))
        ])
    elif provider == "deepseek":
        top = _best([m for m in av if "pro" in m.lower()])
        mid = _best([m for m in av if "flash" in m.lower()])
        light = mid
    elif provider == "together":
        def _params(m: str) -> int:
            nums = re.findall(r"(\d+)\s*b", m.lower())
            return int(nums[-1]) if nums else 0
        # Only rank models with a detectable size — otherwise an unsized,
        # possibly-large model (e.g. DeepSeek-V3) sorts to the cheap 'light' slot.
        sized = sorted([m for m in av if _params(m) > 0], key=_params, reverse=True)
        if sized:
            top = sized[0]
            light = sized[-1]
            # Avoid mid == light on a 2-model list (len//2 == 1 == last index).
            mid = sized[len(sized) // 2] if len(sized) > 2 else sized[0]

    chosen = {
        "top": top or fb.get("top", ""),
        "mid": mid or fb.get("mid", ""),
        "light": light or fb.get("light", ""),
    }
    # Never persist a tier whose model isn't actually in the live catalog: the
    # per-tier hardcoded fallback may name a model this account/catalog doesn't
    # expose, and auto-triage would then call a nonexistent model. Substitute a
    # model that IS available (the heuristic picks are members of `av`).
    if av:
        present = set(av)
        substitute = top or mid or light or av[0]
        for tier in chosen:
            if chosen[tier] and chosen[tier] not in present:
                chosen[tier] = substitute if substitute in present else av[0]
    return chosen


def infer_triage_classifier(provider: str, available: list[str]) -> str | None:
    """The cheap triage/classifier model = inferred 'light' tier."""
    return infer_tier_models(provider, available).get("light") or TRIAGE_CLASSIFIERS.get(provider)


# ── Synchronous resolution (override -> inferred -> hardcoded) ──────────────────

def resolve_tier_model(provider: str, tier: str) -> str | None:
    """Resolve a tier to a concrete model id. Synchronous by contract —
    callers (get_ai_provider, agents/router) run in sync context, so this reads
    the materialized model_tiers store and never lists models live."""
    from core.providers.model_tiers import get_resolved
    return get_resolved(provider).get(tier) or None


def _short_label(model_id: str) -> str:
    """Compact display label from a model id (Together 'org/Name' -> 'Name')."""
    return model_id.split("/")[-1] if model_id else ""


def derive_tier_labels(provider: str, resolved: dict[str, str] | None = None) -> dict[str, str]:
    """Display labels per tier, derived from the resolved model id, with
    TIER_LABELS as fallback. Always non-empty for a known provider so the
    frontend tier switcher never hides itself. Pass an already-loaded
    ``resolved`` map to avoid a redundant store read."""
    if resolved is None:
        from core.providers.model_tiers import get_resolved
        resolved = get_resolved(provider)
    fb = TIER_LABELS.get(provider, {})
    return {
        t: _short_label(resolved.get(t, "")) or fb.get(t, t.title())
        for t in ("top", "mid", "light")
    }


def supports_auto_triage(provider: str) -> bool:
    return provider in TRIAGE_CLASSIFIERS


def get_triage_classifier(provider: str) -> str | None:
    """The cheap classifier model: resolved 'light' tier, else hardcoded."""
    from core.providers.model_tiers import get_resolved
    light = get_resolved(provider).get("light")
    return light or TRIAGE_CLASSIFIERS.get(provider)

/**
 * Chatty — First-login setup wizard.
 *
 * Walks user through AI provider setup and branding configuration.
 * Each step can be skipped; the entire wizard can be dismissed.
 */

import { useState } from 'react';
import { useNavigate } from 'react-router-dom';
import { useTranslation } from 'react-i18next';
import { api } from '../core/api/client';
import { toast } from '../shared/toast';
import { ProviderSetup } from './ProviderSetup';
import type { BrandingConfig } from '../core/types';

type Step = 'welcome' | 'providers' | 'branding';

const STEPS: Step[] = ['welcome', 'providers', 'branding'];

export function SetupWizard() {
  const { t } = useTranslation();
  const [step, setStep] = useState<Step>('welcome');
  const navigate = useNavigate();

  // Branding state
  const [companyName, setCompanyName] = useState('');
  const [accentColor, setAccentColor] = useState('#393c74');
  const [logoUploaded, setLogoUploaded] = useState(false);
  const [saving, setSaving] = useState(false);

  const stepIndex = STEPS.indexOf(step);

  function nextStep() {
    if (stepIndex < STEPS.length - 1) {
      setStep(STEPS[stepIndex + 1]);
    }
  }

  async function finish() {
    try {
      await api('/api/setup/complete', { method: 'POST' });
    } catch { /* navigate regardless */ }
    navigate('/');
  }

  async function skipAll() {
    try {
      await api('/api/setup/skip', { method: 'POST' });
    } catch { /* navigate regardless */ }
    navigate('/');
  }

  async function saveBranding() {
    setSaving(true);
    try {
      const body: Record<string, string> = {};
      if (companyName.trim()) body.company_name = companyName.trim();
      if (accentColor) body.accent_color = accentColor;

      if (Object.keys(body).length > 0) {
        const updated = await api<BrandingConfig>('/api/branding', {
          method: 'PUT',
          body: JSON.stringify(body),
        });
        document.documentElement.style.setProperty('--brand-color', updated.accent_color);
      }

      await finish();
    } catch {
      toast.error(t('setupWizard.errors.finishFailed'));
    } finally {
      setSaving(false);
    }
  }

  async function uploadLogo(file: File) {
    const form = new FormData();
    form.append('file', file);

    const res = await fetch('/api/branding/logo', {
      method: 'POST',
      headers: {
        Authorization: `Bearer ${sessionStorage.getItem('chatty_token')}`,
      },
      body: form,
    });

    if (res.ok) setLogoUploaded(true);
  }

  return (
    <div className="min-h-screen bg-ch-bg flex items-center justify-center p-6">
      <div className="w-full max-w-lg">
        {/* Step indicators */}
        <div className="flex items-center justify-center gap-2 mb-8">
          {STEPS.map((s, i) => (
            <div
              key={s}
              className={`h-1.5 rounded-full transition-all ${
                i <= stepIndex ? 'bg-brand w-10' : 'bg-ch-bg-raised w-6'
              }`}
            />
          ))}
        </div>

        <div className="bg-ch-bg-elev border border-ch-line rounded-md p-8">
          {/* Welcome */}
          {step === 'welcome' && (
            <div className="text-center space-y-6">
              <div className="text-5xl">&#x1f680;</div>

              <h1 className="text-2xl font-bold text-white">
                {t('setupWizard.welcome.title')}
              </h1>

              <p className="text-ch-ink-mute">
                {t('setupWizard.welcome.description')}
              </p>

              <div className="space-y-3 pt-2">
                <button
                  onClick={nextStep}
                  className="w-full py-3 bg-brand text-white font-semibold rounded-md hover:opacity-90 transition"
                >
                  {t('setupWizard.welcome.getStarted')}
                </button>

                <button
                  onClick={skipAll}
                  className="w-full py-3 text-ch-ink-mute hover:text-white text-sm transition"
                >
                  {t('setupWizard.welcome.skipSetup')}
                </button>
              </div>
            </div>
          )}

          {/* AI Providers */}
          {step === 'providers' && (
            <div className="space-y-6">
              <div>
                <h2 className="text-xl font-bold text-white">
                  {t('setupWizard.providers.title')}
                </h2>

                <p className="text-ch-ink-mute text-sm mt-1">
                  {t('setupWizard.providers.description')}
                </p>
              </div>

              <ProviderSetup />

              <div className="flex gap-3 pt-2">
                <button
                  onClick={nextStep}
                  className="flex-1 py-3 bg-brand text-white font-semibold rounded-md hover:opacity-90 transition"
                >
                  {t('setupWizard.providers.continue')}
                </button>

                <button
                  onClick={nextStep}
                  className="py-3 px-5 text-ch-ink-mute hover:text-white text-sm rounded-md hover:bg-ch-bg-raised transition"
                >
                  {t('setupWizard.providers.skip')}
                </button>
              </div>
            </div>
          )}

          {/* Branding */}
          {step === 'branding' && (
            <div className="space-y-6">
              <div>
                <h2 className="text-xl font-bold text-white">
                  {t('setupWizard.branding.title')}
                </h2>

                <p className="text-ch-ink-mute text-sm mt-1">
                  {t('setupWizard.branding.description')}
                </p>
              </div>

              <div>
                <label className="block text-sm text-ch-ink-mute mb-2">
                  {t('setupWizard.branding.platformName')}
                </label>

                <input
