{"path":"frontend/src/agent/AgentPage.tsx","content":"import { useState, useEffect, useCallback, useRef } from 'react';
import { useTranslation } from 'react-i18next';
import { useParams, useNavigate, useSearchParams } from 'react-router-dom';
import { api } from '../core/api/client';
import type { ProviderStatus } from '../core/types';
import { useAgentChat, type ToolMode, type ModelTier } from './hooks/useAgentChat';
import { useLiveMeeting, formatElapsed } from './hooks/useLiveMeeting';
import { useConversations } from './hooks/useConversations';
import { useScrollDirection } from './hooks/useScrollDirection';
import { AgentChatPanel } from './components/AgentChatPanel';
import { AgentContextEditor } from './components/AgentContextEditor';
import { PlaybooksPanel } from './playbooks/PlaybooksPanel';
import { usePlaybooks } from './playbooks/usePlaybooks';
import ReportsPanel from './reports/ReportsPanel';
import HeartbeatPanel from './components/HeartbeatPanel';
import AgentRemindersPanel from './components/AgentRemindersPanel';
import { ConversationSidebar } from './components/ConversationSidebar';
import { AvatarPicker } from './components/AvatarPicker';
import { AvatarMenu } from './components/AvatarMenu';
import { AgentMark } from '../shared/AgentMark';
import { useIsMobile } from '../shared/useIsMobile';
import { MobileMenuDrawer } from '../shared/MobileMenuDrawer';
import { confirmDialog } from '../shared/confirm';
import { toast } from '../shared/toast';
import { ProjectPanel } from './components/ProjectPanel';

interface AgentRow {
  id: string;
  slug: string;
  agent_name: string;
  avatar_url?: string;
  project_root?: string;
  onboarding_complete: boolean;
  gmail_enabled: boolean;
  gmail_send_enabled?: boolean;
  calendar_enabled: boolean;
  calendar_write_enabled?: boolean;
  drive_enabled?: boolean;
  drive_write_enabled?: boolean;
  telegram_enabled: boolean;
  telegram_bot_token: string;
  telegram_bot_username: string;
  telegram_group_enabled: boolean;
  model_tier?: string;
  provider_override?: string;
}

type Tab = 'chat' | 'knowledge'| 'project' | 'playbooks' | 'reports' | 'reminders' | 'heartbeat';

function parseTab(raw: string | null): Tab | null {
  if (!raw) return null;
  if (raw === 'activity') return 'heartbeat';
  if (['chat', 'knowledge', 'playbooks', 'reports', 'reminders', 'heartbeat'].includes(raw)) return raw as Tab;
  return null;
}

const TABS: { key: Tab; labelKey: string }[] = [
  { key: 'chat', labelKey: 'agentPage.tabs.chat' },
  { key: 'knowledge', labelKey: 'agentPage.tabs.knowledge' },
  { key: 'project', labelKey: 'agentPage.tabs.project' },
  { key: 'playbooks', labelKey: 'agentPage.tabs.playbooks' },
  { key: 'reports', labelKey: 'agentPage.tabs.reports' },
  { key: 'reminders', labelKey: 'agentPage.tabs.reminders' },
  { key: 'heartbeat', labelKey: 'agentPage.tabs.heartbeat' },
];

const TOOL_MODES: { key: ToolMode; labelKey: string }[] = [
  { key: 'read-only', labelKey: 'agentPage.toolModes.read' },
  { key: 'normal', labelKey: 'agentPage.toolModes.normal' },
  { key: 'power', labelKey: 'agentPage.toolModes.power' },
];

export function AgentPage() {
  const { t } = useTranslation();
  const { id: agentId } = useParams<{ id: string }>();
  const navigate = useNavigate();
  const [searchParams, setSearchParams] = useSearchParams();

  const [agent, setAgent] = useState<AgentRow | null>(null);
  const [activeTab, setActiveTab] = useState<Tab>(() => parseTab(searchParams.get('tab')) || 'chat');
  const [showAvatarPicker, setShowAvatarPicker] = useState(false);
  const [avatarMenuRect, setAvatarMenuRect] = useState<DOMRect | null>(null);
  const [showSidebar, setShowSidebar] = useState(false);
  const [openaiAvailable, setOpenaiAvailable] = useState(false);
  const [alwaysPowerMode, setAlwaysPowerMode] = useState(false);
  const [avatarCacheBust, setAvatarCacheBust] = useState(0);
  const [activeProvider, setActiveProvider] = useState('');
  const [modelTier, setModelTier] = useState<ModelTier>('auto');
  const [tierLabels, setTierLabels] = useState<Record<string, string>>({});
  const [globalModelTier, setGlobalModelTier] = useState<ModelTier>('auto');
  const isMobile = useIsMobile();
  const prevOnboardingComplete = useRef<boolean | null>(null);

  const apiPrefix = `/api/agents/${agentId}`;
  const convs = useConversations(apiPrefix);
  const pb = usePlaybooks(apiPrefix);

  const handleTitleUpdate = useCallback((convId: string, title: string) => {
    convs.updateConversationTitle(convId, title);
    convs.loadConversations();
  }, [convs]);

  const importCompleteRef = useRef<((id: string) => void) | null>(null);
  const onboardingCompleteRef = useRef<(() => void) | null>(null);

  const chat = useAgentChat(apiPrefix, {
    onTitleUpdate: handleTitleUpdate,
    onImportComplete: (id) => importCompleteRef.current?.(id),
    onOnboardingComplete: () => onboardingCompleteRef.current?.(),
  });

  // Live meeting recorder + coach. The hook reads these callbacks through a
  // per-render ref, so fresh chat/convs closures are always used.
  const live = useLiveMeeting(apiPrefix, {
    conversationId: chat.conversationId,
    onCoachMessage: (msg, sessConvId) => {
      if (chat.conversationId === sessConvId) chat.appendMessage(msg);
      // Other conversations: the nudge is persisted server-side and loads
      // normally when that conversation is opened.
    },
    onSessionConversation: async (convId) => {
      if (chat.conversationId === convId) return;
      if (!chat.conversationId) {
        chat.adoptConversation(convId);
        convs.loadConversations();
        return;
      }
      // Reattach while a different conversation is open → switch to the
      // meeting conversation (same flow as the import redirect above).
      await convs.loadConversations();
      const msgs = await convs.selectConversation(convId);
      if (msgs) chat.loadMessages(msgs, convId);
    },
    onSessionEnded: async (sessConvId) => {
      if (chat.conversationId !== sessConvId || chat.isStreaming) return;
      const msgs = await convs.selectConversation(sessConvId);
      if (msgs) chat.loadMessages(msgs, sessConvId);
    },
  });

  useEffect(() => {
    importCompleteRef.current = async (newConversationId: string) => {
      await convs.loadConversations();
      const msgs = await convs.selectConversation(newConversationId);
      if (msgs) chat.loadMessages(msgs, newConversationId);
    };
    onboardingCompleteRef.current = () => {
      if (agentId) api<AgentRow>(`/api/agents/${agentId}`).then(a => { setAgent(a); chat.setTrainingMode(false); }).catch(() => { chat.setTrainingMode(false); });
    };
  }); // intentionally no deps — always tracks latest convs/chat

  const scrollRef = useRef<HTMLDivElement>(null);
  const restoredConversationRef = useRef<string | null>(null);
  const topBarVisible = useScrollDirection(scrollRef);

  useEffect(() => {
    if (!agentId) return;
    localStorage.setItem('chatty_last_agent', agentId);
    api<AgentRow>(`/api/agents/${agentId}`)
      .then(a => {
        setAgent(a);
        if (a.model_tier) setModelTier(a.model_tier as ModelTier);
      })
      .catch(() => navigate('/'));
  }, [agentId, navigate]);

  useEffect(() => {
    if (!agentId) return;
    api<{ generate_available: boolean }>(`/api/agents/${agentId}/avatar/availability`)
      .then(d => setOpenaiAvailable(d.generate_available))
      .catch(() => {}); // best-effort: hides "Generate with AI" when unknown
  }, [agentId]);

  useEffect(() => {
    api<ProviderStatus>('/api/providers')
      .then(p => { setActiveProvider(p.active_provider); })
      .catch(() => {}); // best-effort: tier labels degrade gracefully
  }, []);

  // Fetch tier labels and resolve for the agent's provider
  useEffect(() => {
    if (!agent) return;
    const providerKey = agent.provider_override || activeProvider;
    if (!providerKey) return;
    api<{ tier_labels: Record<string, Record<string, string>> }>('/api/providers/tiers')
      .then(d => setTierLabels(d.tier_labels[providerKey] || {}))
      .catch(() => {}); // best-effort: tier labels degrade gracefully
  }, [agent, activeProvider]);


  const handleSwitchTier = useCallback(async (tier: ModelTier) => {
    if (!agentId) return;
    const prev = modelTier;
    setModelTier(tier);
    try {
      await api(`/api/agents/${agentId}`, {
        method: 'PUT',
        body: JSON.stringify({ model_tier: tier }),
      });
    } catch {
      // best-effort: revert the optimistic tier change on failure
      setModelTier(prev);
    }
  }, [agentId, modelTier]);

  useEffect(() => {
    api<{ always_power_mode: boolean; default_model_tier: string }>('/api/setup/admin-settings')
      .then(s => {
        setAlwaysPowerMode(s.always_power_mode);
        if (s.always_power_mode) chat.setToolMode('power');
        setGlobalModelTier((s.default_model_tier || 'auto') as ModelTier);
      })
      .catch(() => {}); // best-effort: defaults apply when settings unavailable
