{"path":"frontend/src/agent/hooks/useAgentChat.ts","content":"/**
 * Chatty — useAgentChat hook.
 *
 * Streams chat responses via SSE. Handles text, tool_start, tool_args,
 * tool_end, confirm, plan_ready, usage, report, title_update, done, error events.
 *
 * Supports 3-tier tool mode (read-only / normal / power) with confirmation flow,
 * plan mode, training/improve modes, and context usage tracking.
 *
 * Performance: rAF-batched text deltas, tail-update pattern for message state,
 * messagesRef for stable closures.
 */

import { useState, useCallback, useRef, useEffect } from 'react';
import { getToken } from '../../core/auth/tokenUtils';
import type { ContextUsage } from '../../core/types';

function uuid(): string {
  if (typeof crypto !== 'undefined' && crypto.randomUUID) return crypto.randomUUID();
  return 'xxxxxxxx-xxxx-4xxx-yxxx-xxxxxxxxxxxx'.replace(/[xy]/g, c => {
    const r = (Math.random() * 16) | 0;
    return (c === 'x' ? r : (r & 0x3) | 0x8).toString(16);
  });
}

export type ToolMode = 'read-only' | 'normal' | 'power';
export type ModelTier = 'auto' | 'top' | 'mid' | 'light';
export type TrainingType = 'topic' | 'improve' | null;

export interface ToolCallInfo {
  tool: string;
  toolUseId: string;
  status: 'running' | 'done' | 'error';
  args?: Record<string, unknown>;
  description?: string;
  result?: unknown;
  elapsedMs?: number;
  durationMs?: number;
  startedAt: number;
}

export interface PendingConfirmation {
  tool: string;
  args: Record<string, unknown>;
  toolUseId: string;
  // DB id of the pending assistant row, echoed back on approval so the backend
  // reconciles the exact row even when a provider reuses tool ids (Gemini).
  msgId?: string;
  status: 'pending' | 'approved' | 'denied';
  description?: string;
}

export interface PendingPlan {
  plan: string;
  status: 'pending' | 'approved' | 'iterating';
}

export interface InlineReport {
  id: string;
  title: string;
  subtitle?: string;
  sections: unknown[];
  created_at: string;
}

export interface ChatMessage {
  id: string;
  role: 'user' | 'assistant';
  content: string;
  timestamp: number;
  toolCalls?: ToolCallInfo[];
  isStreaming?: boolean;
  attachments?: { name: string; size: number }[];
  hidden?: boolean;
  pendingConfirm?: PendingConfirmation;
  pendingPlan?: PendingPlan;
  reports?: InlineReport[];
  model?: string;
  tier?: string;
  playbook?: { slug: string; name: string };
  compacted?: boolean;  // context was compacted just before this turn's response
  // Live audio-transcription progress (pre-stream phase of an upload turn).
  // Not persisted — present only while/after this session's turn streamed.
  transcription?: { filename: string; stage: string; message: string; percent: number | null };
}

// ContextUsage lives in core/types as the single source of truth; re-exported
// here so existing importers (AgentChatPanel) keep their import path.
export type { ContextUsage };

// Insert an out-of-band message (live-meeting coach nudge) into the list.
// Pure and exported for tests. Duplicate ids are dropped (SSE replay ×
// history reload overlap); if the tail is mid-stream the message goes just
// before it — every streaming writer targets prev[prev.length-1], so
// appending would corrupt the in-flight reply.
export function insertMessage(list: ChatMessage[], msg: ChatMessage): ChatMessage[] {
  if (list.some(m => m.id === msg.id)) return list;
  const last = list[list.length - 1];
  if (last?.isStreaming) {
    return [...list.slice(0, -1), msg, last];
  }
  return [...list, msg];
}

interface Options {
  onTitleUpdate?: (convId: string, title: string) => void;
  onImportComplete?: (newConversationId: string) => void;
  onOnboardingComplete?: () => void;
}

export function useAgentChat(apiPrefix: string, options?: Options) {
  const [messages, setMessages] = useState<ChatMessage[]>([]);
  const [isStreaming, setIsStreaming] = useState(false);
  const [conversationId, setConversationId] = useState<string | null>(null);
  const [trainingMode, setTrainingModeState] = useState(false);
  const [trainingType, setTrainingType] = useState<TrainingType>('topic');
  const [planMode, setPlanModeState] = useState(false);
  const [toolMode, setToolMode] = useState<ToolMode>('normal');
  const [contextUsage, setContextUsage] = useState<ContextUsage | null>(null);
  const [greetingPending, setGreetingPending] = useState(false);
  const abortRef = useRef<AbortController | null>(null);
  const streamInIntervalRef = useRef<ReturnType<typeof setInterval> | null>(null);
  useEffect(() => () => {
    if (streamInIntervalRef.current) clearInterval(streamInIntervalRef.current);
  }, []);
  const savedToolModeRef = useRef<ToolMode>('normal');
  const savedToolModeForPlanRef = useRef<ToolMode>('normal');
  const trainingKickoffRef = useRef(false);
  const trainingKickoffMessageRef = useRef('Hey there!');

  // Stable ref for messages — avoids stale closures in sendMessage
  const messagesRef = useRef<ChatMessage[]>([]);
  useEffect(() => { messagesRef.current = messages; }, [messages]);

  // ── rAF text batching ─────────────────────────────────────────────
  const pendingTextRef = useRef('');
  const rafIdRef = useRef<number | null>(null);

  const flushPendingText = useCallback(() => {
    rafIdRef.current = null;
    const chunk = pendingTextRef.current;
    if (!chunk) return;
    pendingTextRef.current = '';
    setMessages(prev => {
      if (!prev.length) return prev;
      const last = prev[prev.length - 1];
      if (last.role !== 'assistant') return prev;
      return [...prev.slice(0, -1), { ...last, content: last.content + chunk }];
    });
  }, []);

  const scheduleFlush = useCallback(() => {
    if (rafIdRef.current !== null) return;
    rafIdRef.current = requestAnimationFrame(flushPendingText);
  }, [flushPendingText]);

  // ── Tail-update helper ────────────────────────────────────────────
  const updateLastAssistant = useCallback(
    (updater: (msg: ChatMessage) => ChatMessage) => {
      setMessages(prev => {
        if (!prev.length) return prev;
        const last = prev[prev.length - 1];
        if (last.role !== 'assistant') return prev;
        return [...prev.slice(0, -1), updater(last)];
      });
    },
    []
  );

  const sendMessage = useCallback(async (text: string, files?: File[], approvedTool?: {
    tool: string;
    args: Record<string, unknown>;
    toolUseId: string;
    msgId?: string;
    result: unknown;
  }, overrides?: {
      tool_mode?: string;
      plan_mode?: boolean;
      hidden?: boolean;
      playbook?: { slug: string; name: string };
      continuation_resume?: boolean;
      conversation_id?: string;
    }) => {
    const playbook = overrides?.playbook;
    // The [playbook:slug] marker rides in the persisted content (like the
    // "[via Telegram from X]" prefix) so the reference survives history
    // reloads; the payload field below triggers this turn's expansion.
    const continuationResume = overrides?.continuation_resume === true;
    const content = playbook ? `[playbook:${playbook.slug}] ${text}`.trimEnd() : text;
    const userMsg: ChatMessage = {
      id: uuid(),
      role: 'user',
      content,
      timestamp: Date.now(),
      attachments: files?.map(f => ({ name: f.name, size: f.size })),
      hidden: overrides?.hidden,
      playbook,
    };
    const assistantMsg: ChatMessage = {
      id: uuid(),
      role: 'assistant',
      content: '',
      timestamp: Date.now(),
      toolCalls: [],
      isStreaming: true,
    };

    setMessages(prev =>
      continuationResume
        ? [...prev, assistantMsg]
        : [...prev, userMsg, assistantMsg]
    );
    setIsStreaming(true);

    // Server-side assembly: the backend rebuilds the full conversation from the
    // DB by conversation_id (with full tool results), so send ONLY the new
    // message — not the whole transcript. For an approved write tool the new
    // message is the "[Approved] <tool>" marker, which the backend reconciles
    // onto the pending row rather than persisting as a user turn.
    const history = continuationResume
      ? []
      : [{ role: userMsg.role, content: userMsg.content }];

    // Effective tool mode: training forces power
    const effectiveMode = overrides?.tool_mode ?? (trainingMode ? 'power' : toolMode);

    abortRef.current = new AbortController();

    try {
      const token = getToken();
      const hasFiles = files && files.length > 0;

      const payload: Record<string, unknown> = {
        messages: history,
        training_mode: trainingMode,
        training_type: trainingType,
        conversation_id: overrides?.conversation_id ?? conversationId,
        tool_mode: effectiveMode,
        plan_mode: overrides?.plan_mode ?? planMode,
        continuation_resume: continuationResume,
      };
      if (approvedTool) payload.approved_tool = approvedTool;
      if (playbook) payload.playbook_slug = playbook.slug;

      let res: Response;
      if (hasFiles) {
        const formData = new FormData();
        formData.append('payload', JSON.stringify(payload));
        for (const f of files) {
          formData.append('files', f);
        }
        res = await fetch(`${apiPrefix}/chat/upload`, {
          method: 'POST',
          headers: {
            ...(token ? { Authorization: `Bearer ${token}` } : {}),
          },
          body: formData,
          signal: abortRef.current.signal,
        });
      } else {
        res = await fetch(`${apiPrefix}/chat`, {
          method: 'POST',
          headers: {
            'Content-Type': 'application/json',
            ...(token ? { Authorization: `Bearer ${token}` } : {}),
          },
          body: JSON.stringify(payload),

{"path":"frontend/src/agent/components/AgentChatPanel.tsx","content":"import { useState, useRef, useEffect, useCallback, useMemo, Fragment, type RefObject, type KeyboardEvent, type DragEvent, type MouseEvent } from 'react';
import { useTranslation } from 'react-i18next';
import type { ChatMessage, ContextUsage, ToolMode, ModelTier } from '../hooks/useAgentChat';
import type { AgentAlert } from '../../core/types';
import { AgentMessageBubble } from './AgentMessageBubble';
import { DateDivider } from './DateDivider';
import AlertBanner from './AlertBanner';
import NotificationLog from './NotificationLog';
import { IconAttach, IconArrowUp, IconMic, IconZap } from '../../shared/icons';
import type { LiveStatus } from '../hooks/useLiveMeeting';
import { useIsMobile } from '../../shared/useIsMobile';
import { api } from '../../core/api/client';
import { toast } from '../../shared/toast';
import { localDateKey } from '../utils/dateFormat';
import { PlaybookChipsRow } from '../playbooks/PlaybookChipsRow';
import { SlashCommandMenu } from '../playbooks/SlashCommandMenu';
import { integrationLabel, type PlaybookSummary } from '../playbooks/types';

const ALLOWED_EXTENSIONS = new Set(['csv', 'xlsx', 'md', 'txt', 'pdf', 'docx']);
// Meeting recordings — transcribed server-side (audio or video; only the
// audio track is used). Mirrors AUDIO_EXTENSIONS in the backend.
const AUDIO_EXTENSIONS = new Set([
  'mp3', 'm4a', 'wav', 'ogg', 'oga', 'opus', 'flac', 'aac', 'aiff',
  'mp4', 'mov', 'webm', 'mpga', 'mpeg',
]);
const MAX_FILE_SIZE = 1 * 1024 * 1024;
const MAX_PDF_SIZE = 10 * 1024 * 1024;
// Soft sanity cap for recordings (~4h meeting as MP4). The backend chunks
// arbitrarily long audio; this just catches obviously wrong drops.
const MAX_AUDIO_SIZE = 2 * 1024 * 1024 * 1024;
const MAX_FILES = 5;

function getExtension(name: string): string {
  return (name.split('.').pop() || '').toLowerCase();
}

interface Props {
  messages: ChatMessage[];
  isStreaming: boolean;
  onSend: (text: string, files?: File[], opts?: { playbook?: { slug: string; name: string } }) => void;
  onStop: () => void;
  onApprove?: (msgId: string) => void;
  onDeny?: (msgId: string) => void;
  onApprovePlan?: (msgId: string) => void;
  onIteratePlan?: (msgId: string) => void;
  scrollRef?: RefObject<HTMLDivElement | null>;
  contextUsage?: ContextUsage | null;
  toolMode?: ToolMode;
  onToolModeChange?: (mode: ToolMode) => void;
  alwaysPowerMode?: boolean;
  agentName?: string;
  agentSlug?: string;
  conversationSource?: string | null;
  importMode?: boolean;
  onCancelImport?: () => void;
  greetingPending?: boolean;
  modelTier?: ModelTier;
  tierLabels?: Record<string, string>;
  onSwitchTier?: (tier: ModelTier) => void;
  playbooks?: PlaybookSummary[];
  onOpenPlaybooks?: () => void;
  liveStatus?: LiveStatus;
  onStartLive?: (prep?: string) => void;
  liveError?: string | null;
}

const TOOL_MODES: { key: ToolMode; labelKey: string }[] = [
  { key: 'read-only', labelKey: 'agentChat.toolModes.read' },
  { key: 'normal', labelKey: 'agentChat.toolModes.normal' },
  { key: 'power', labelKey: 'agentChat.toolModes.power' },
];

const TIER_KEYS: ModelTier[] = ['auto', 'top', 'mid', 'light'];

type QueuedMessage = { text: string; files: File[]; playbook: PlaybookSummary | null };

export function AgentChatPanel({
  messages, isStreaming, onSend, onStop, onApprove, onDeny,
  onApprovePlan, onIteratePlan, scrollRef: externalScrollRef,
  contextUsage, toolMode, onToolModeChange, alwaysPowerMode, agentName, agentSlug, conversationSource, importMode, onCancelImport,
  greetingPending,
  modelTier, tierLabels, onSwitchTier,
  playbooks, onOpenPlaybooks,
  liveStatus, onStartLive, liveError,
}: Props) {
  const { t } = useTranslation();
  const [input, setInput] = useState('');
  const [pendingFiles, setPendingFiles] = useState<File[]>([]);
  const [showRecordPrep, setShowRecordPrep] = useState(false);
  const [prepText, setPrepText] = useState('');
  // Prep row stays open through 'starting' (so a mic-denied error is visible)
  // and closes itself once recording actually begins.
  useEffect(() => {
    if (liveStatus === 'recording') {
      // eslint-disable-next-line react-hooks/set-state-in-effect
      setShowRecordPrep(false);
      setPrepText('');
    }
  }, [liveStatus]);
  const [dragOver, setDragOver] = useState(false);
  const [fileError, setFileError] = useState<string | null>(null);
  const [alerts, setAlerts] = useState<AgentAlert[]>([]);
  const [stagedPlaybook, setStagedPlaybook] = useState<PlaybookSummary | null>(null);
  const [slashIndex, setSlashIndex] = useState(0);
  // Type-ahead: a draft submitted while the agent is still streaming is held
  // here and auto-sent the moment the turn ends. The ref lets the completion
  // effect read it without re-subscribing; the state drives the "queued" pill.
  const [queued, setQueued] = useState<QueuedMessage | null>(null);
  const queuedRef = useRef<QueuedMessage | null>(null);
  const stashQueue = (q: QueuedMessage | null) => { queuedRef.current = q; setQueued(q); };
  const internalScrollRef = useRef<HTMLDivElement>(null);

  useEffect(() => {
    if (!agentSlug) return;
    let cancelled = false;
    (async () => {
      try {
        const res = await api<{ alerts: AgentAlert[] }>(`/api/alerts?agent=${agentSlug}`);
        if (!cancelled) setAlerts(res.alerts);
      } catch { /* alerts are supplementary */ }
    })();
    return () => { cancelled = true; };
  }, [agentSlug]);
  const scrollContainerRef = externalScrollRef || internalScrollRef;
  const textareaRef = useRef<HTMLTextAreaElement>(null);
  const fileInputRef = useRef<HTMLInputElement>(null);

  const scrollRafRef = useRef<number | null>(null);
  useEffect(() => {
    if (scrollRafRef.current !== null) return;
    scrollRafRef.current = requestAnimationFrame(() => {
      scrollRafRef.current = null;
      const el = scrollContainerRef.current;
      if (el) el.scrollTop = el.scrollHeight;
    });
    return () => {
      if (scrollRafRef.current !== null) {
        cancelAnimationFrame(scrollRafRef.current);
        scrollRafRef.current = null;
      }
    };
  }, [messages, scrollContainerRef]);

  useEffect(() => {
    if (!isStreaming) textareaRef.current?.focus();
  }, [isStreaming]);

  useEffect(() => {
    if (!fileError) return;
    const id = setTimeout(() => setFileError(null), 4000);
    return () => clearTimeout(id);
  }, [fileError]);

  const validateAndAddFiles = useCallback((incoming: File[]) => {
    const errors: string[] = [];
    const valid: File[] = [];

    for (const f of incoming) {
      const ext = getExtension(f.name);
      const allowed = importMode
        ? new Set([...ALLOWED_EXTENSIONS, ...AUDIO_EXTENSIONS, 'zip'])
        : new Set([...ALLOWED_EXTENSIONS, ...AUDIO_EXTENSIONS]);
      if (!allowed.has(ext)) { errors.push(t('agentChat.files.unsupportedType', { name: f.name, ext })); continue; }
      const maxSize = AUDIO_EXTENSIONS.has(ext) ? MAX_AUDIO_SIZE
        : ext === 'zip' ? 25 * 1024 * 1024 : (ext === 'pdf' || ext === 'docx') ? MAX_PDF_SIZE : MAX_FILE_SIZE;
      const maxLabel = AUDIO_EXTENSIONS.has(ext) ? '2 GB'
        : ext === 'zip' ? '25 MB' : (ext === 'pdf' || ext === 'docx') ? '10 MB' : '1 MB';
      if (f.size > maxSize) { errors.push(t('agentChat.files.exceedsSize', { name: f.name, max: maxLabel })); continue; }
      if (f.size === 0) { errors.push(t('agentChat.files.emptyFile', { name: f.name })); continue; }
      if (pendingFiles.some(p => p.name === f.name)) { errors.push(t('agentChat.files.alreadyAttached', { name: f.name })); continue; }
      valid.push(f);
    }

    const remaining = MAX_FILES - pendingFiles.length;
    if (valid.length > remaining) {
      errors.push(t('agentChat.files.maxFiles', { max: MAX_FILES, dropped: valid.length - remaining }));
      valid.splice(remaining);
    }

    if (errors.length) setFileError(errors.join(' '));
    if (valid.length) setPendingFiles(prev => [...prev, ...valid]);
  }, [pendingFiles, importMode]);

  function removeFile(idx: number) { setPendingFiles(prev => prev.filter((_, i) => i !== idx)); }
  function handleDragOver(e: DragEvent) { e.preventDefault(); setDragOver(true); }
  function handleDragLeave(e: DragEvent) { e.preventDefault(); setDragOver(false); }
  function handleDrop(e: DragEvent) {
    e.preventDefault(); setDragOver(false);
    const files = Array.from(e.dataTransfer.files);
    if (files.length) validateAndAddFiles(files);
  }

  // ── Playbook staging + slash menu state machine ─────────────────────
  // Open is derived from the input ("/" as first char), so typing and
  // backspacing naturally open/filter/close the menu.
  const activePlaybooks = useMemo(
    () => (playbooks || []).filter(p => !p.archived),
    [playbooks],
  );
  const slashOpen = !importMode && input.startsWith('/') && !stagedPlaybook && activePlaybooks.length > 0;
  const slashQuery = slashOpen ? input.slice(1).toLowerCase() : '';
  const slashMatches = useMemo(
    () => activePlaybooks.filter(p =>
      p.name.toLowerCase().includes(slashQuery) || p.description.toLowerCase().includes(slashQuery)),
    [activePlaybooks, slashQuery],
  );

  // The highlight resets where the query changes (typing / opening the menu),
  // not via an effect — react-hooks/set-state-in-effect.

  function stagePlaybook(p: PlaybookSummary) {
    if (!p.available) {
      const needs = p.missing_integrations.map(integrationLabel).join(', ');
      toast.info(t('agentChat.playbooks.needsIntegration', { name: p.name, needs }));
      return;
    }
    setStagedPlaybook(p);
    setInput('');
    textareaRef.current?.focus();
  }

  function handleKeyDown(e: KeyboardEvent<HTMLTextAreaElement>) {
    if (slashOpen) {
      if (e.key

